-- 368 — Markets as a first-class dataset.
--
-- WHAT THIS ANSWERS. Until now a "market" was a row in `research_market_directory`
-- (slug, name, a supplied count) plus whatever a company happened to have in its
-- single `sector` column. That is a list of labels. This file makes the market a
-- record with its own identity, its own sourced observations, and explicit
-- relationships to the companies and funds in it.
--
-- THE ONE RULE THE WHOLE DATASET RESTS ON: every quantitative claim is an
-- individual observation with a source and a date, and `research_market_metrics`
-- is APPEND-ONLY. A newer market size does not overwrite an older one, because
-- the older one was true on its publication date and the change between them is
-- itself a signal. Nothing here computes a number; everything here records one
-- that somebody published, with `source_url` and `retrieved_at` attached.
--
-- WHERE A NUMBER IS ABSENT IT STAYS ABSENT. There is no licensed market-intelligence
-- source in this deployment (no Dealroom, Harmonic, Crunchbase, PitchBook, Tracxn,
-- CB Insights or Preqin feed), no commercial market-research feed (Gartner, IDC,
-- Statista, IBISWorld), and no fund or deal register. Those tables are created and
-- seeded empty ON PURPOSE: the API and the UI render "Not recorded" from a missing
-- row, which is a statement a reader can trust, and the alternative — filling them
-- with plausible figures — is the failure this dataset exists to prevent.
--
-- HIERARCHY IS SUPPORTED AND NOT ASSERTED. `parent_market_id` exists, is indexed,
-- and is left NULL for every seeded market: the 82 taxonomy labels are flat, and a
-- hierarchy typed in by hand is exactly the "taxonomy as source of truth" mistake
-- the dataset is meant to avoid. A parent gets set when a source defines it.
--
-- IDEMPOTENT. Every seed is `ON CONFLICT ... DO NOTHING/DO UPDATE` keyed on a
-- deterministic id, and the two derivations (company links, industry notes) are
-- INSERT..SELECT over data that is already in the database.

-- ---------------------------------------------------------------------------
-- The market record
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_markets (
  market_id TEXT PRIMARY KEY,
  market_name TEXT NOT NULL,
  canonical_name TEXT,
  parent_market_id TEXT REFERENCES research_markets(market_id),
  market_type TEXT NOT NULL DEFAULT 'sector',

  sector TEXT,
  industry TEXT,
  subindustry TEXT,
  category TEXT,
  vertical TEXT,
  technology_category TEXT,

  description TEXT,
  definition TEXT,
  inclusion_criteria TEXT,
  exclusion_criteria TEXT,

  global_market INTEGER,
  countries TEXT,
  regions TEXT,
  primary_markets TEXT,
  emerging_markets TEXT,

  market_stage TEXT,
  market_maturity TEXT,
  fragmentation TEXT,
  concentration TEXT,
  consolidation_trend TEXT,

  demand_drivers TEXT,
  customer_segments TEXT,
  buyer_types TEXT,
  use_cases TEXT,

  key_players TEXT,
  leading_companies TEXT,
  emerging_companies TEXT,
  incumbents TEXT,

  competitive_intensity TEXT,
  barriers_to_entry TEXT,
  switching_costs TEXT,
  substitutes TEXT,

  technologies TEXT,
  technology_trends TEXT,
  enabling_technologies TEXT,
  disruptive_technologies TEXT,

  regulatory_environment TEXT,
  regulatory_changes TEXT,
  licensing_requirements TEXT,

  market_trends TEXT,
  emerging_trends TEXT,
  declining_trends TEXT,
  catalysts TEXT,
  risks TEXT,

  market_start_date TEXT,
  inflection_points TEXT,
  adoption_stage TEXT,
  forecast_horizon TEXT,

  axal_thesis TEXT,
  axal_relevance TEXT,
  axal_focus TEXT,

  source_id TEXT,
  source_name TEXT NOT NULL DEFAULT 'Axal taxonomy',
  source_type TEXT,
  source_url TEXT,
  publication_date TEXT,
  retrieved_at TEXT,
  verified_at TEXT,
  confidence REAL,

  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_research_markets_parent ON research_markets(parent_market_id);
CREATE INDEX IF NOT EXISTS idx_research_markets_name ON research_markets(market_name COLLATE NOCASE);

-- ---------------------------------------------------------------------------
-- Sourced observations — append only, never overwritten
--
-- A "correction" is another row: the previous observation stands as the record of
-- what was published then. `market_metric_id` is deterministic for a given
-- (market, metric, period, geography, source), so re-ingesting the same publication
-- is a no-op while a new period adds a row.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_metrics (
  market_metric_id TEXT PRIMARY KEY,
  market_id TEXT NOT NULL,
  metric_name TEXT NOT NULL,
  metric_value REAL,
  metric_text TEXT,
  metric_unit TEXT,
  currency TEXT,
  period_start TEXT,
  period_end TEXT,
  base_year INTEGER,
  forecast_year INTEGER,
  geography TEXT,
  source_id TEXT,
  source_name TEXT,
  source_url TEXT,
  publication_date TEXT,
  retrieved_at TEXT NOT NULL,
  confidence REAL,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_research_market_metrics_market
  ON research_market_metrics(market_id, metric_name, base_year);

-- ---------------------------------------------------------------------------
-- Where a market stands in relation to a company
--
-- The relationship carries the meaning the company's single `sector` column never
-- could: a company can be core in one market, adjacent in another, a supplier in a
-- third, and the row says which.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_companies (
  id TEXT PRIMARY KEY,
  market_id TEXT NOT NULL,
  company_uid TEXT NOT NULL,
  relationship_type TEXT NOT NULL DEFAULT 'core',
  primary_market INTEGER NOT NULL DEFAULT 0,
  secondary_market INTEGER NOT NULL DEFAULT 0,
  market_share REAL,
  market_share_year INTEGER,
  relevance TEXT,
  source_id TEXT,
  source_url TEXT,
  verified_at TEXT,
  confidence REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (market_id, company_uid, relationship_type)
);
CREATE INDEX IF NOT EXISTS idx_research_market_companies_market
  ON research_market_companies(market_id, relationship_type);
CREATE INDEX IF NOT EXISTS idx_research_market_companies_company
  ON research_market_companies(company_uid);

-- ---------------------------------------------------------------------------
-- Funds in a market
--
-- Empty on purpose: there is no licensed fund or deal register in this
-- deployment. The table, the route and the UI exist so that the day one is
-- licensed, the market page shows it without a schema change.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_funds (
  id TEXT PRIMARY KEY,
  market_id TEXT NOT NULL,
  fund_uid TEXT,
  fund_name TEXT NOT NULL,
  relationship_type TEXT NOT NULL DEFAULT 'investor',
  focus_level TEXT,
  investment_count INTEGER,
  recent_investment_count INTEGER,
  source_id TEXT,
  source_url TEXT,
  verified_at TEXT,
  confidence REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (market_id, fund_name, relationship_type)
);
CREATE INDEX IF NOT EXISTS idx_research_market_funds_market ON research_market_funds(market_id);

-- ---------------------------------------------------------------------------
-- Rounds and deals
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_investments (
  id TEXT PRIMARY KEY,
  market_id TEXT NOT NULL,
  company_uid TEXT,
  company_name TEXT NOT NULL,
  round_type TEXT,
  -- Integer cents, like every other money column in this schema, and named so
  -- the guard can see it (check-money-cents). A round's size is reported in
  -- millions and stored in cents, which is lossless for any published figure and
  -- keeps it out of the float type the ledger rule exists to prevent.
  amount_cents INTEGER,
  currency TEXT,
  announced_at TEXT,
  investors TEXT,
  source_id TEXT,
  source_url TEXT,
  retrieved_at TEXT NOT NULL,
  confidence REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (market_id, company_name, round_type, announced_at, source_url)
);
CREATE INDEX IF NOT EXISTS idx_research_market_investments_market
  ON research_market_investments(market_id, announced_at);

-- ---------------------------------------------------------------------------
-- Everything else that is a sourced statement about a market
--
-- Trends, technologies, customer segments, use cases, competitors, exits, events,
-- forecasts, regulation, risks and catalysts are the same shape: a label, a detail
-- somebody published, an optional value with a unit, a source and a date. Nineteen
-- near-identical link tables would be nineteen places to forget the citation.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_facets (
  id TEXT PRIMARY KEY,
  market_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  label TEXT NOT NULL,
  detail TEXT,
  value REAL,
  unit TEXT,
  geography TEXT,
  observed_at TEXT,
  source_id TEXT,
  source_url TEXT,
  confidence REAL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (market_id, kind, label, source_url)
);
CREATE INDEX IF NOT EXISTS idx_research_market_facets_market ON research_market_facets(market_id, kind);

-- ---------------------------------------------------------------------------
-- Where a market fact came from
--
-- `source_type` is the dataset's honesty switch: 'primary' and 'research' can
-- carry a number, 'alternative' carries a proxy, and 'axal' carries what Axal
-- itself asserts (the taxonomy's discovery counts, for instance) — never dressed
-- as an external measurement.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS research_market_sources (
  source_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  source_type TEXT NOT NULL,
  homepage TEXT,
  license TEXT,
  quality_weight REAL,
  notes TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- ---------------------------------------------------------------------------
-- The sources this dataset actually holds anything from
-- ---------------------------------------------------------------------------
INSERT INTO research_market_sources (source_id, name, source_type, homepage, license, quality_weight, notes)
VALUES
  ('axal_taxonomy', 'Axal sector taxonomy', 'axal', NULL, NULL, NULL,
   'The 82 sector labels and their supplied company counts. Axal''s own assertion, not an external measurement.'),
  ('wikidata', 'Wikidata (CC0 entity records)', 'primary', 'https://www.wikidata.org', 'CC0 for Wikidata data; website links are references', 0.7,
   'Identity facts only: legal/official name, official website, country, inception, industry classification. CC0.'),
  ('hn_discussion', 'Hacker News discussion', 'alternative', 'https://hn.algolia.com/api', 'Public API terms', 0.5,
   'Practitioner discussion via the free, keyless Algolia HN Search API. A proxy for attention, not demand.'),
  ('github_activity', 'GitHub repository activity', 'alternative', 'https://docs.github.com/en/rest/search', 'Public API terms', 0.6,
   'Public repository activity via the keyless GitHub REST API. A proxy for engineering attention.'),
  ('stackexchange_questions', 'Stack Exchange question activity', 'alternative', 'https://api.stackexchange.com/docs', 'CC BY-SA for content', 0.55,
   'Question volume via the keyless Stack Exchange API. A proxy for implementation friction.')
ON CONFLICT(source_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Seed: every taxonomy sector becomes a market record
--
-- The identity comes from the directory row the markets page already reads, so
-- the two cannot drift apart by a rename. `market_id` is the taxonomy slug the
-- route takes; `market_name` is the label the signal feed and the company
-- directory are both keyed by.
--
-- THE `WHERE` IS SYNTAX, NOT TASTE. SQLite cannot parse `INSERT … SELECT …
-- ON CONFLICT` without a WHERE: `ON` is ambiguous between the upsert clause and
-- a join, and the parser refuses the statement with a bare "syntax error near
-- DO". `check-runtime-schema-declared` executes every migration against real
-- SQLite and caught exactly this before it reached D1 — D1 is the same parser,
-- so it would have failed in production too. The predicate is also true of
-- every directory row (a slug is the key the page routes on), so it filters
-- nothing out.
-- ---------------------------------------------------------------------------
INSERT INTO research_markets
  (market_id, market_name, canonical_name, market_type, source_id, source_name, source_type, retrieved_at)
SELECT d.slug, d.name, d.name, 'sector', 'axal_taxonomy', COALESCE(d.source_name, 'Axal taxonomy'),
       'axal', COALESCE(d.as_of, date('now'))
  FROM research_market_directory d
 WHERE d.slug IS NOT NULL AND trim(d.slug) <> ''
ON CONFLICT(market_id) DO UPDATE SET
  market_name = excluded.market_name,
  canonical_name = excluded.canonical_name,
  updated_at = datetime('now');

-- ---------------------------------------------------------------------------
-- Seed: the supplied count is recorded as an observation, not as a column
--
-- This is the number printed on the card. It enters the dataset as what it is —
-- Axal's supplied discovery count, with its date — and not as TAM, market size or
-- a verified census. It is the first row of a time series that can grow.
-- ---------------------------------------------------------------------------
INSERT INTO research_market_metrics
  (market_metric_id, market_id, metric_name, metric_value, metric_unit, base_year,
   source_id, source_name, source_url, retrieved_at, confidence, note)
SELECT 'axal_taxonomy:' || d.slug || ':supplied_company_count:' || COALESCE(d.as_of, date('now')),
       d.slug, 'supplied_company_count', d.company_count, 'companies',
       CAST(substr(COALESCE(d.as_of, date('now')), 1, 4) AS INTEGER),
       'axal_taxonomy', COALESCE(d.source_name, 'Axal taxonomy'), NULL,
       COALESCE(d.as_of, datetime('now')), NULL,
       COALESCE(d.source_boundary, 'A supplied discovery count, not TAM or valuation.')
  FROM research_market_directory d
 WHERE d.company_count IS NOT NULL
ON CONFLICT(market_metric_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Derivation: the market -> company graph the company directory already holds
--
-- The relationship `core` is the honest one here: the record is in this market's
-- universe by the industry its sector resolved to, and nothing more is claimed —
-- no market share, no role, no rank. `verified_at` is the date the record was
-- pulled, which is what the reader is being told.
-- ---------------------------------------------------------------------------
INSERT INTO research_market_companies
  (id, market_id, company_uid, relationship_type, primary_market, relevance,
   source_id, source_url, verified_at, confidence)
SELECT 'universe:' || m.market_id || ':' || c.uid, m.market_id, c.uid, 'core', 1,
       'In this market''s universe: Wikidata records the company in an industry the taxonomy label resolves to.',
       'wikidata', c.source_url, c.as_of, 0.7
  FROM research_company_directory c
  JOIN research_markets m ON lower(trim(c.sector)) = lower(trim(m.market_name))
 WHERE c.sector IS NOT NULL AND trim(c.sector) <> ''
ON CONFLICT(id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Seed: how each market's company universe was resolved
--
-- A sector label is not a market definition, so each market records the Wikidata
-- industry items it was resolved through and how many companies with an official
-- website Wikidata holds in each — the reader can open the entity and check.
-- ---------------------------------------------------------------------------

